from typing import Optional, Protocol

class EvictionPolicy(Protocol):
    def pick(self, keys: list[str]) -> str: ...

class LruPolicy:                      # conforms structurally, no inheritance needed
    def pick(self, keys: list[str]) -> str: return keys[0]

class Cache:
    def __init__(self, policy: Optional[EvictionPolicy] = None) -> None:
        self.policy, self.items = policy or LruPolicy(), {}
    def victim(self, keys: list[str]) -> str: return self.policy.pick(keys)
